INSERT INTO `success_stories` (`id`, `groom_name`, `bride_name`, `marriage_date`, `city`, `state`, `groom_photo`, `bride_photo`, `couple_photo`, `wedding_photo`, `story_title`, `short_description`, `full_story`, `family_message`, `rating`, `is_featured`, `display_order`, `status`, `created_by`, `created_at`, `updated_at`, `deleted_at`) VALUES
(1, 'Ankit Kailash Kankariya', 'Sayalee Satish Patil', '2026-08-08', 'Kolhapur', 'Maharashtra', 'uploads/success_stories/1785302088_groom_WhatsApp Image 2026-07-28 at 10.08.14 AM.jpeg', 'uploads/success_stories/1785302088_bride_WhatsApp Image 2026-07-28 at 10.08.14 AM.jpeg', 'uploads/success_stories/1785302088_couple_WhatsApp Image 2026-07-28 at 10.08.14 AM.jpeg', 'uploads/success_stories/1785302088_wedding_WhatsApp Image 2026-07-28 at 10.08.14 AM.jpeg', 'Ankit Sayalee', 'Short Description', 'Full Story', 'Jai Jinendra Milind Sir 🙏🙏\r\n\r\nI\'m Archana Patil from Kolhapur.\r\n\r\nDear Sir,\r\n\r\nWe would like to express our heartfelt gratitude to you and the entire Aaryans Manomilan team for your sincere efforts and guidance in helping us find a suitable match for our daughter.\r\n\r\nWith the support of *Aaryans Manomilan*, this important journey became much smoother, more reassuring, and truly meaningful for our family.\r\n\r\nWe sincerely appreciate the professionalism, patience, and dedication with which you understood our expectations and guided us at every step. Your commitment and continuous support played a valuable role in bringing two families together.\r\n\r\nWe are truly grateful to Aaryans Manomilan for making this beautiful relationship possible.\r\n\r\nThank you once again for your excellent service and for the remarkable efforts you are taking for the Jain community. We wish you and the entire *Aaryans Manomilan* team continued success in helping many more families find happiness and lifelong companionship.\r\n\r\nWith warm regards,\r\n\r\nArchana Patil & Family 🙏', 5, 0, 0, 'Active', 1, '2026-07-29 05:12:48', '2026-08-07 04:15:38', NULL),
(2, 'Yash Palase', 'Sakshi Vankundre', NULL, 'pune', 'Maharashtra', NULL, 'uploads/success_stories/1785387420_bride_Sakshi vankundr and Yash.jpeg', 'uploads/success_stories/1785387420_couple_yash and sakshi.jpeg', NULL, 'Yash and Sakshi', NULL, NULL, 'सप्रेम नमस्कार.🙏🏻\r\n\r\nआमचा चिरंजीव यश याची नोंदणी आर्यन्स मनोमिलन या जैन वधू-वर सूचक संकेतस्थळावर केली होती. त्या वेळी आपण दाखविलेला विश्वास आणि दिलेले मार्गदर्शन आज किती मोलाचे ठरले, याची मनापासून जाणीव होत आहे.\r\n\r\nकाही दिवसांपूर्वी पुण्यात आर्यन्स मनोमिलनतर्फे आयोजित करण्यात आलेल्या भव्य वधू-वर मेळाव्यास कौटुंबिक कारणांमुळे आम्हाला उपस्थित राहता आले नाही. त्याची थोडी खंत नक्कीच होती. मात्र आर्यन्स मनोमिलनच्या माध्यमातून आम्हाला अनेक चांगली स्थळे पाहण्याची संधी मिळाली. त्यापैकी एका योग्य स्थळासोबत काल यशचा सुपारी समारंभ पार पडला आणि विवाह निश्चित झाला. मुलीचे नाव साक्षी राहुल वनकुद्रे असून ती पुण्यातील एका बहुराष्ट्रीय कंपनीत सॉफ्टवेअर इंजिनिअर म्हणून कार्यरत आहे. दोन्ही कुटुंबांना हा संबंध मनापासून पसंत पडला आणि अत्यंत आनंददायी वातावरणात हा निर्णय झाला.\r\n\r\nया आनंदाच्या क्षणी आर्यन्स मनोमिलन आणि त्यामागे निःस्वार्थपणे, कोणत्याही अपेक्षेशिवाय कार्य करणारे श्री. मिलिंद सर, तसेच सर्व पदाधिकारी, कार्यकर्ते आणि स्वयंसेवक यांचे आम्ही मनःपूर्वक आभार मानतो.\r\n\r\nआजच्या धावपळीच्या आणि बदलत्या जीवनशैलीत योग्य जीवनसाथीचा शोध घेणे हे अनेक कुटुंबांसाठी मोठे आव्हान बनले आहे. अशा वेळी समाजातील उपवर वधू-वर आणि त्यांच्या पालकांना विश्वासार्ह, सुसंस्कृत आणि सुरक्षित व्यासपीठ उपलब्ध करून देणे, ही केवळ सेवा नसून समाजाला जोडणारे एक मोठे कार्य आहे. आर्यन्स मनोमिलनच्या या उपक्रमामुळे अनेक कुटुंबांच्या आयुष्यात आनंदाचे क्षण निर्माण होत आहेत आणि अनेक नवीन नाती जुळत आहेत.\r\n\r\nआपल्या सर्वांच्या अथक परिश्रमांचे हे एक सुंदर फळ आमच्या कुटुंबालाही अनुभवता आले. म्हणूनच आपल्या प्रयत्नांना मिळालेल्या यशाची ही आनंदवार्ता आपणापर्यंत पोहोचावी, तसेच आर्यन्स मनोमिलनमुळे कित्येक कुटुंबांची स्वप्ने पूर्ण होत आहेत, याची जाणीव आपल्यालाही व्हावी, या भावनेतून हा संदेश पाठवत आहोत.\r\n\r\nआपण आणि आर्यन्स मनोमिलनचा संपूर्ण परिवार असेच निःस्वार्थपणे समाजकार्य करत राहावा, अधिकाधिक कुटुंबांच्या आयुष्यात आनंदाचे क्षण निर्माण करावेत आणि अनेकांना योग्य जीवनसाथी मिळवून द्यावा, हीच मनःपूर्वक शुभेच्छा.\r\n\r\nपुन्हा एकदा श्री. मिलिंद सर आणि आर्यन्स मनोमिलनच्या संपूर्ण टीमचे मनःपूर्वक आभार.\r\n\r\nआपल्या पुढील सर्व सामाजिक उपक्रमांसाठी हार्दिक शुभेच्छा!\r\n\r\nधन्यवाद. 🙏🏼', 5, 0, 0, 'Active', 1, '2026-07-30 04:57:00', '2026-08-03 09:43:04', NULL),
(3, 'Ketan Dipak Shaha', 'Nikita Yogesh Shah', NULL, 'Phaltan', 'Maharashtra', 'uploads/success_stories/1785388132_groom_Ketan.jpeg', 'uploads/success_stories/1785388072_bride_WhatsApp Image 2026-07-30 at 10.35.42 AM.jpeg', 'uploads/success_stories/1785388132_couple_success story ketan and nikita.jpeg', NULL, 'Ketan and Nikita', NULL, NULL, NULL, 5, 0, 0, 'Active', 1, '2026-07-30 05:07:52', '2026-07-30 05:08:52', NULL);
